def fires(b):
    return b.last_col == 1 and b.heights[1] == 1

def level(b):
    if not fires(b):
        return 0
    if b.ply <= 4:
        return 9
    if b.ply <= 6:
        return 6
    if b.ply <= 12:
        return 5
    return 4

def col1_fresh(b):
    # last stone went in column 1 and I (player to move) have no stone in column 1
    if b.last_col != 1:
        return False
    return all(b.grid[r][1] != 1 for r in range(6))

def opening4(b):
    if b.ply != 4:
        return False
    return len(set(b.moves)) >= 3

def fires(b):
    return col1_fresh(b) or opening4(b)

def level(b):
    if col1_fresh(b):
        n = b.heights[1]
        if n == 1:
            if b.ply <= 4:
                return 9
            if b.ply <= 7:
                return 7
            return 5
        return 3
    if opening4(b):
        return 3
    return 0

def col1_first(b):
    # the stone just played is the first stone in column 1
    return b.last_col == 1 and b.heights[1] == 1

def opening4(b):
    # 4-stone opening, all stones in different columns, column 1 untouched
    return b.ply == 4 and len(set(b.moves)) == 4 and b.heights[1] == 0

def fires(b):
    return col1_first(b) or opening4(b)

def level(b):
    if col1_first(b):
        if b.ply <= 4:
            return 9
        if b.ply <= 7:
            return 7
        return 5
    if b.last_col == 1 and b.heights[1] == 2 and b.grid[0][1] == 2:
        return 3
    if opening4(b):
        return 3
    if b.ply == 4 and b.heights[1] == 0:
        return 2
    return 0

def col1_theirs(b):
    # the stone just played is in column 1 and every stone in column 1 is theirs (none of mine)
    return b.last_col == 1 and all(b.grid[r][1] != 1 for r in range(b.heights[1]))

def col1_hit(b):
    if not col1_theirs(b):
        return False
    return b.heights[1] == 1 or (b.heights[1] == 2 and b.ply <= 6)

def opening4(b):
    # 4-stone opening, all stones in different columns, column 1 untouched
    return b.ply == 4 and len(set(b.moves)) == 4 and b.heights[1] == 0

def fires(b):
    return col1_hit(b) or opening4(b)

def level(b):
    if col1_hit(b):
        if b.heights[1] == 2:
            return 6
        if b.ply <= 4:
            return 9
        if b.ply <= 7:
            return 7
        return 5
    if col1_theirs(b) and b.heights[1] == 2:
        return 3
    if opening4(b):
        return 3
    if b.ply == 4 and b.heights[1] == 0:
        return 2
    return 0
